AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_01DfGDMq2qATcGdeUAmheKUp', arguments={'file_text': 'const { AxePuppeteer } = require('@axe-core/puppeteer');
const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage();
  const url = 'file://' + path.resolve(__dirname, 'index.html');
  await page.goto(url);

  async function run(label) {
    const results = await new AxePuppeteer(page).analyze();
    console.log(`\n=== ${label} ===`);
    console.log('violations:', results.violations.length);
    for (const v of results.violations) {
      console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
      v.nodes.forEach(n => console.log('   ', n.target, '|', n.failureSummary?.split('\n')[0]));
    }
  }

  await run('Initial');
  // Trigger error state
  await page.click('button[type="submit"]');
  await run('After invalid submit');

